				remainingArgs++
			}
			for rewind := 0; rewind < remainingArgs; rewind++ {
				exprDispenser.Prev()
			}
			exprMatcher := new(caddyhttp.MatchExpression)
			if remainingArgs == 0 {
				return exprDispenser.ArgErr()
			}
			exprDispenser.NextArg()
			exprMatcher.Expr = exprDispenser.Val()
